#include <stdio.h>

static void bajar(long nivel) {
    char relleno[64];                              /* algo de espacio en cada llamada */
    relleno[0] = (char)nivel;
    if (nivel % 25000 == 0) fprintf(stderr, "nivel %6ld: local en %p\n", nivel, (void *)relleno);
    bajar(nivel + 1);                              /* sin condición de corte: recursión infinita */
    relleno[1] = relleno[0];                       /* impide que el compilador lo convierta en un bucle */
}

int main(void) { bajar(0); return 0; }
